public TopicDetail get(String slug) {
    String key = "topic:slug:" + slug;
    String cached = stringRedisTemplate.opsForValue().get(key);
    if (cached != null) {
        return objectMapper.readValue(cached, TopicDetail.class);
    }
    TopicDetail detail = topicRepository.findPublished(slug);
    stringRedisTemplate.opsForValue()
            .set(key, objectMapper.writeValueAsString(detail), Duration.ofMinutes(5));
    return detail;
}
